/**
 * One row of the allow-list, as the checkbox grid renders it.

**Every active task type, plus any inactive one this project still
allows.** The second half is not tidiness: the `PUT` is a wholesale
replace assembled from these rows, so a retired task type that was
allowed and is not rendered would be dropped by the next save through a
screen that never showed it. That is the failure
`replaceSlaPolicies` guards against for project-level defaults, one
master over. An inactive row carries `isActive: false` so the screen can
label it rather than silently offering a type no new ticket can use.

 */
export interface ProjectSettingsTaskType {
  taskTypeId: number;
  code?: string;
  name: string;
  /** True for every row when `restrictsTaskTypes` is false. That is not
padding — an unrestricted project really does allow all of them, and
a client rendering checkboxes needs the same answer either way.
 */
  isAllowed: boolean;
  /** `task_types.is_active`. False only on a retired type this project
still has a row for; an unrestricted project never shows one,
because "all active types" is what it means.
 */
  isActive: boolean;
}
